import React, { useState } from 'react';
import axios from 'axios';

function AgentModal({
  agent,
  purchased,
  accessStatus,
  authToken,
  apiBase,
  onClose,
  onLoadAgents
}) {
  const [question, setQuestion] = useState('');
  const [response, setResponse] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showPurchasePrompt, setShowPurchasePrompt] = useState(false);
  const [purchaseLoading, setPurchaseLoading] = useState(false);
  const [purchaseSuccess, setPurchaseSuccess] = useState(null);

  const handleAsk = async (e) => {
    e.preventDefault();
    if (!question.trim()) return;

    setError('');
    setResponse('');
    setLoading(true);

    try {
      const res = await axios.post(
        `${apiBase}/agents/${agent.id}/ask`,
        { question: question.trim() },
        {
          headers: {
            Authorization: `Bearer ${authToken}`,
            'Content-Type': 'application/json'
          }
        }
      );

      setResponse(res.data.response);
      setQuestion('');
      onLoadAgents();
    } catch (err) {
      if (err.response?.status === 402) {
        setShowPurchasePrompt(true);
        setError('Demo limit reached! Please purchase to continue.');
        onLoadAgents();
      } else {
        setError(err.response?.data?.detail || 'Error asking agent');
      }
    } finally {
      setLoading(false);
    }
  };

  const demoUsesLeft = accessStatus.demo_uses_left || 0;
  const isPurchased = accessStatus.is_purchased;

  return (
    <div
      className="modal-overlay"
      onClick={onClose}
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: 'rgba(0,0,0,0.7)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 1000
      }}
    >
      <div
        className="modal-content"
        style={{
          backgroundColor: '#1e293b',
          borderRadius: '0.5rem',
          padding: '2rem',
          maxWidth: '600px',
          width: '90%',
          maxHeight: '90vh',
          overflow: 'auto',
          border: '1px solid #475569'
        }}
        onClick={(e) => e.stopPropagation()}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
          <h2 style={{ margin: 0, fontSize: '1.5rem' }}>{agent.name}</h2>
          <button
            onClick={onClose}
            style={{
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              fontSize: '1.5rem',
              color: '#94a3b8'
            }}
          >
            ✕
          </button>
        </div>

        <p style={{ color: '#cbd5e1', marginBottom: '1rem' }}>{agent.description}</p>

        <div style={{ marginBottom: '1.5rem', padding: '1rem', backgroundColor: '#0f172a', borderRadius: '0.5rem' }}>
          <h4 style={{ margin: '0 0 0.5rem 0', color: '#f97316' }}>Purpose</h4>
          <p style={{ margin: 0, color: '#cbd5e1' }}>{agent.purpose}</p>
        </div>

        <div style={{ marginBottom: '1.5rem', padding: '1rem', backgroundColor: '#0f172a', borderRadius: '0.5rem' }}>
          <h4 style={{ margin: '0 0 0.5rem 0', color: '#f97316' }}>Capabilities</h4>
          <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
            {agent.capabilities.map((cap, idx) => (
              <span
                key={idx}
                style={{
                  backgroundColor: '#1e293b',
                  color: '#f97316',
                  padding: '0.25rem 0.75rem',
                  borderRadius: '9999px',
                  fontSize: '0.875rem',
                  border: '1px solid #f97316'
                }}
              >
                {cap}
              </span>
            ))}
          </div>
        </div>

        <div style={{ marginBottom: '1.5rem', padding: '1rem', backgroundColor: '#0f172a', borderRadius: '0.5rem' }}>
          <h4 style={{ margin: '0 0 0.5rem 0', color: '#f97316' }}>Status</h4>
          <div style={{ display: 'flex', gap: '1rem' }}>
            <div>
              <span style={{ color: '#94a3b8' }}>Operational: </span>
              <span style={{ color: '#86efac' }}>{agent.status}</span>
            </div>
            <div>
              {isPurchased ? (
                <span style={{ color: '#86efac' }}>✓ Owned</span>
              ) : (
                <span style={{ color: '#f97316' }}>Demo: {demoUsesLeft} try{demoUsesLeft !== 1 ? 'ies' : ''} left</span>
              )}
            </div>
          </div>
        </div>

        {showPurchasePrompt ? (
          <div style={{ padding: '1rem', backgroundColor: '#7c2d12', borderRadius: '0.5rem', borderLeft: '4px solid #f97316', marginBottom: '1rem' }}>
            <h4 style={{ margin: '0 0 0.5rem 0', color: '#fedd5e' }}>Demo Limit Reached</h4>
            <p style={{ margin: 0, color: '#fed7aa' }}>
              You've used all your demo tries for this agent. Please purchase to continue using it.
            </p>
            <button
              className="btn btn-primary"
              style={{ marginTop: '1rem' }}
              onClick={() => alert('Purchase feature coming soon!')}
            >
              Purchase Now
            </button>
          </div>
        ) : (
          <form onSubmit={handleAsk} style={{ marginBottom: '1rem' }}>
            <div style={{ marginBottom: '1rem' }}>
              <label style={{ display: 'block', marginBottom: '0.5rem', color: '#e2e8f0' }}>
                Ask a question:
              </label>
              <textarea
                value={question}
                onChange={(e) => setQuestion(e.target.value)}
                disabled={loading || (!isPurchased && demoUsesLeft === 0)}
                style={{
                  width: '100%',
                  padding: '0.75rem',
                  backgroundColor: '#0f172a',
                  color: '#e2e8f0',
                  border: '1px solid #475569',
                  borderRadius: '0.375rem',
                  fontFamily: 'inherit',
                  fontSize: '0.875rem',
                  minHeight: '100px',
                  resize: 'vertical',
                  opacity: !isPurchased && demoUsesLeft === 0 ? 0.5 : 1
                }}
                placeholder="Type your question here..."
              />
            </div>
            <button
              type="submit"
              disabled={loading || !question.trim() || (!isPurchased && demoUsesLeft === 0)}
              className="btn btn-primary"
              style={{
                opacity: loading || !question.trim() || (!isPurchased && demoUsesLeft === 0) ? 0.5 : 1
              }}
            >
              {loading ? 'Asking...' : 'Ask Agent'}
            </button>
          </form>
        )}

        {error && (
          <div style={{ padding: '1rem', backgroundColor: '#7c2d12', borderRadius: '0.5rem', borderLeft: '4px solid #f97316', marginBottom: '1rem', color: '#fed7aa' }}>
            {error}
          </div>
        )}

        {response && (
          <div style={{ padding: '1rem', backgroundColor: '#0f172a', borderRadius: '0.5rem', borderLeft: '4px solid #86efac' }}>
            <h4 style={{ margin: '0 0 0.5rem 0', color: '#86efac' }}>Response</h4>
            <p style={{ margin: 0, color: '#cbd5e1', whiteSpace: 'pre-wrap' }}>{response}</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default AgentModal;
